CREATE OR REPLACE FUNCTION sample.check_work_minutes()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if new.work_minutes < 0 then
        raise exception 'work_minutes must not be negative';
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION sample.count_rows(p_table_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_count bigint;
begin
    if p_table_name = 'employee' then
        select count(*) into v_count from employee;
    else
        execute format('select count(*) from sample.%I', p_table_name) into v_count;
    end if;
    return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION sample.employee_directory_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_department_id integer;
begin
    select department_id into v_department_id
    from sample.department
    where department_name = new.department_name;

    insert into sample.employee(employee_code, employee_name, department_id)
    values (new.employee_code, new.employee_name, v_department_id);
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION sample.log_employee_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    insert into sample.audit_log(table_name, record_id, action, changed_by)
    values ('employee', coalesce(new.employee_id, old.employee_id), tg_op, current_user);
    if tg_op = 'DELETE' then
        return old;
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION sample.notify_truncate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    raise notice 'sample.project_assignment was truncated';
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION sample.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    new.updated_at := now();
    return new;
end;
$function$
